static void require(bool b,const char*label){if(!b){fprintf(stderr,"FAIL: %s\n",label);std::exit(1);}printf("PASS: %s\n",label);}
static void set(SynthMavenProcessor&p,const String&id,float v){auto*parameter=p.parameters.getParameter(id);require(parameter!=nullptr,"parameter available");parameter->setValueNotifyingHost(v);}
static std::shared_ptr<MavenSample> sine(){auto s=std::make_shared<MavenSample>();s->name="Test sine";s->audio.setSize(1,44100);for(int i=0;i<44100;i++)s->audio.setSample(0,i,.3f*std::sin(2*MathConstants<double>::pi*440*i/44100));return s;}
static double frequency(MavenSampler&s,int note){s.panic();s.midi(MidiMessage::noteOn(1,note,(uint8)127));float b[2];int crosses=0;float previous=0;for(int i=0;i<12000;i++){s.render(b);if(!std::isfinite(b[0]))std::abort();if(i>2000&&previous<=0&&b[0]>0)crosses++;previous=b[0];}return crosses*44100./9999.;}
static double play(SynthMavenProcessor&p,int note,int blocks=70){p.prepareToPlay(44100,256);AudioBuffer<float>b(2,256);MidiBuffer m;double energy=0;for(int n=0;n<blocks;n++){if(n==0)m.addEvent(MidiMessage::noteOn(1,note,(uint8)120),0);p.processBlock(b,m);if(n>20)for(int ch=0;ch<2;ch++)for(int i=0;i<256;i++){float v=b.getSample(ch,i);if(!std::isfinite(v))std::abort();energy+=std::abs(v);}}return energy;}
static void screenshot(AudioProcessorEditor&editor,const File&file){Image image(Image::ARGB,editor.getWidth(),editor.getHeight(),true);Graphics g(image);editor.paintEntireComponent(g,true);auto stream=file.createOutputStream();stream->setPosition(0);stream->truncate();PNGImageFormat png;png.writeImageToStream(image,*stream);}
static Button*button(Component&c,const String&text){if(auto*b=dynamic_cast<Button*>(&c))if(b->getButtonText()==text)return b;for(int i=0;i<c.getNumChildComponents();i++)if(auto*b=button(*c.getChildComponent(i),text))return b;return nullptr;}
static ComboBox*sectionSelector(Component&c){if(auto*box=dynamic_cast<ComboBox*>(&c))if(box->getNumItems()>0&&box->getItemText(0)=="All sections")return box;for(int n=0;n<c.getNumChildComponents();n++)if(auto*box=sectionSelector(*c.getChildComponent(n)))return box;return nullptr;}
int main(int argc,char**argv){ScopedJuceInitialiser_GUI gui;MavenSampler sampler;sampler.setSample(sine());MavenSampleSettings settings;std::array<double,128>tuning{};sampler.setSettings(settings,tuning);
 for(auto pair:{std::make_pair(48,220.),std::make_pair(60,440.),std::make_pair(72,880.)})require(std::abs(frequency(sampler,pair.first)-pair.second)<8,"sampler chromatic pitch tracking");
 tuning[60]=-50;sampler.setSettings(settings,tuning);require(std::abs(frequency(sampler,60)-440*std::pow(2.,-50./1200))<8,"sampler applies microtuning");
 settings.mode=1;settings.reverse=1;settings.start=.9f;settings.end=.90001f;settings.loopStart=1;settings.loopEnd=0;sampler.setSettings(settings,tuning);sampler.midi(MidiMessage::noteOn(1,127,(uint8)127));float output[2];for(int n=0;n<1000;n++){sampler.render(output);if(!std::isfinite(output[0]))std::abort();}
 SynthMavenProcessor p;auto file=File::getCurrentWorkingDirectory().getChildFile("sampler-test.wav");{WavAudioFormat format;auto stream=file.createOutputStream();std::unique_ptr<AudioFormatWriter>w(format.createWriterFor(stream.get(),44100,1,24,{},0));require(w!=nullptr,"test WAV writer");stream.release();auto source=sine();w->writeFromAudioSampleBuffer(source->audio,0,44100);}
 String error;require(p.loadSample(0,file,error),"audio import");set(p,p.sampleId(0,"mode"),1);require(play(p,60)>10,"imported audio responds to notes");
 set(p,p.layerId(0,"mute"),1);require(play(p,60)<.001,"layer mute silences output");set(p,p.layerId(0,"mute"),0);set(p,"masterMute",1);require(play(p,60)<.001,"master mute silences output");set(p,"masterMute",0);
 require(p.loadSample(1,file,error),"second sample layer");set(p,p.sampleId(1,"mode"),1);set(p,p.layerId(0,"gain"),0);set(p,p.layerId(0,"solo"),1);require(play(p,60)<.001,"solo excludes other enabled layers");set(p,p.layerId(0,"solo"),0);require(play(p,60)>10,"removing solo restores other layer");set(p,p.layerId(1,"enabled"),0);set(p,p.layerId(0,"gain"),1);
 set(p,p.layerId(0,"split"),1);set(p,p.layerId(0,"splitPoint"),60.f/127);set(p,p.layerId(0,"splitSide"),0);require(play(p,60)>10,"lower split includes boundary note");require(play(p,61)<.001,"lower split rejects upper notes");set(p,p.layerId(0,"splitSide"),1);require(play(p,60)<.001&&play(p,61)>10,"upper split excludes boundary and accepts upper notes");set(p,p.layerId(0,"split"),0);
 set(p,"masterGain",.5f);double half=play(p,60);set(p,"masterGain",1);double full=play(p,60);require(half/full>.49&&half/full<.51,"master fader scales output independently");
 set(p,p.layerId(0,"gain"),.5f);half=play(p,60);set(p,p.layerId(0,"gain"),1);full=play(p,60);require(half/full>.49&&half/full<.51,"layer fader scales output independently");
 MavenUI::MixerStrip strip(p,0,[](int){});strip.octUp.onClick();require(std::abs(p.parameters.getRawParameterValue(p.layerId(0,"transpose"))->load()-.75f)<.001,"octave up changes only selected layer by 12 semitones");strip.octDown.onClick();require(std::abs(p.parameters.getRawParameterValue(p.layerId(0,"transpose"))->load()-.5f)<.001,"octave down restores transpose");MavenUI::SplitPopup routing(p,0);routing.mode.setSelectedId(2,sendNotificationSync);require(p.parameters.getRawParameterValue(p.layerId(0,"split"))->load()>=.5f,"Layer popup enables split routing");routing.point.setSelectedId(70,sendNotificationSync);require(routing.point.getText()=="A4"&&std::abs(p.parameters.getRawParameterValue(p.layerId(0,"splitPoint"))->load()-69.f/127)<.001,"split selector uses note names and stores correct pitch");routing.mode.setSelectedId(1,sendNotificationSync);
 for(double rate:{44100.,48000.,88200.,96000.,192000.})for(int block:{1,127,512}){p.prepareToPlay(rate,block);AudioBuffer<float>audio(2,block);MidiBuffer midi;double energy=0;for(int n=0;n<8192/block+1;n++){if(n==0)midi.addEvent(MidiMessage::noteOn(1,60,(uint8)100),0);p.processBlock(audio,midi);for(int c=0;c<2;c++)for(int j=0;j<block;j++){float value=audio.getSample(c,j);if(!std::isfinite(value)||std::abs(value)>1.001f)std::abort();energy+=std::abs(value);}}require(energy>0,"sampler renders at host rate and block size");}
 MemoryBlock state;p.getStateInformation(state);file.deleteFile();SynthMavenProcessor restored;restored.setStateInformation(state.getData(),(int)state.getSize());require(restored.sampleForLayer(0)!=nullptr&&restored.sampleEnabled(0),"sample embedded and restored without original file");require(play(restored,60)>10,"embedded sample plays after restore");require(restored.layerInstrument(0)=="SAMPLER","sampler identity restored");
 OscillatorRack rack;rack.settings[0]=0;rack.settings[1]=1;rack.settings[5]=1;rack.settings[13]=0;rack.settings[15]=1;rack.midi(MidiMessage::noteOn(1,69,(uint8)127));int crossings=0;float previous=0;for(int n=0;n<44100;n++){float audio[2]{};rack.render(audio);if(!std::isfinite(audio[0])||!std::isfinite(audio[1]))require(false,"oscillator finite");if(n>1000&&previous<=0&&audio[0]>0)crossings++;previous=audio[0];}require(std::abs(crossings-430)<3,"oscillator 2 tracks A4 at 440 Hz");rack.midi(MidiMessage::noteOff(1,69));for(int n=0;n<44100;n++){float audio[2]{};rack.render(audio);}require(!rack.voices[0].active,"oscillator note-off releases voice");rack.panic();rack.settings[17]=1;rack.settings[20]=1;rack.settings[23]=1;double tail=0;for(int n=0;n<22050;n++){float audio[2]={n==0?1.f:0.f,n==0?1.f:0.f};rack.settings[0]=1;rack.render(audio);if(!std::isfinite(audio[0])||!std::isfinite(audio[1]))require(false,"modulation effects remain finite");if(n>100)tail+=std::abs(audio[0])+std::abs(audio[1]);}require(tail>.01,"chorus and flanger produce delayed stereo output");
 ParameterGraphic sampleEnvelope(p,ParameterGraphic::Envelope,6,ParameterGraphic::Sample);sampleEnvelope.write(6,.42f);require(std::abs(p.parameters.getRawParameterValue(p.sampleId(0,"attack"))->load()-.42f)<.001,"sample envelope graph edits sampler attack");ParameterGraphic oscillatorEnvelope(p,ParameterGraphic::Envelope,13,ParameterGraphic::Rack);oscillatorEnvelope.write(16,.36f);require(std::abs(p.parameters.getRawParameterValue(p.layerId(0,"oscRelease"))->load()-.36f)<.001,"auxiliary envelope graph edits oscillator release");ParameterGraphic chorusGraph(p,ParameterGraphic::ModDelay,17,ParameterGraphic::Rack);chorusGraph.write(19,.7f);require(std::abs(p.parameters.getRawParameterValue(p.layerId(0,"chorusDepth"))->load()-.7f)<.001,"chorus graph edits effect depth");ParameterGraphic envelope(p,ParameterGraphic::Envelope);envelope.write(1,.6f);envelope.write(3,.4f);require(std::abs(envelope.value(1)-.6f)<.001&&std::abs(envelope.value(3)-.4f)<.001,"graph edits share host parameter state");envelope.setSize(600,160);auto handles=envelope.handles();require(handles[0].x<handles[1].x&&handles[1].x<handles[2].x,"envelope handles follow attack decay release order");
 if(argc>1){SynthMavenProcessor overviewProcessor;std::unique_ptr<AudioProcessorEditor>overview(overviewProcessor.createEditor());overview->setSize(1024,1366);auto*all=button(*overview,"ALL PARAMETERS");all->setToggleState(true,dontSendNotification);all->onClick();overview->resized();screenshot(*overview,File(argv[1]).getChildFile("SynthMaven-parameters.png"));auto*sections=sectionSelector(*overview);require(sections!=nullptr,"graphical section selector exists");for(auto entry:{std::make_pair(String("02 /"),String("SynthMaven-envelope.png")),std::make_pair(String("03 /"),String("SynthMaven-filter.png")),std::make_pair(String("05 /"),String("SynthMaven-lfo.png")),std::make_pair(String("11 / DELAY ECHO"),String("SynthMaven-delay.png")),std::make_pair(String("11 / REVERB TAIL"),String("SynthMaven-reverb.png")),std::make_pair(String("11 / EQUALIZER"),String("SynthMaven-eq.png"))}){for(int n=0;n<sections->getNumItems();n++)if(sections->getItemText(n).startsWith(entry.first)){sections->setSelectedItemIndex(n,sendNotificationSync);break;}screenshot(*overview,File(argv[1]).getChildFile(entry.second));}auto*fx=button(*overview,"EFFECTS");fx->setToggleState(true,dontSendNotification);fx->onClick();screenshot(*overview,File(argv[1]).getChildFile("SynthMaven-effects.png"));std::unique_ptr<AudioProcessorEditor>editor(restored.createEditor());editor->setSize(1440,1100);auto*b=button(*editor,"LAYERS");require(b!=nullptr,"mixer tab exists");b->setToggleState(true,dontSendNotification);b->onClick();editor->resized();screenshot(*editor,File(argv[1]).getChildFile("SynthMaven-mixer.png"));b=button(*editor,"SAMPLER");require(b!=nullptr,"sampler tab exists");b->setToggleState(true,dontSendNotification);b->onClick();editor->resized();screenshot(*editor,File(argv[1]).getChildFile("SynthMaven-sampler.png"));}
 puts("PASS: chromatic sampler, tuning, reverse/loop bounds, mixer mute/solo/master, split boundaries, portable sample state and shared UI");}
